/**
 * @description nemo内置请求单例
 * axios
 */

class NemoCoreManager {
  static singleInstance = null as NemoCoreManager;

  static getSingleInstance() {
    if (!NemoCoreManager.singleInstance) {
      NemoCoreManager.singleInstance = new NemoCoreManager();
      return NemoCoreManager.singleInstance;
    }
    return NemoCoreManager.singleInstance;
  }

  /**
   * request 请求
   * @param url 请求url
   * @param options fetch 请求配置
   */
  fetch(url: string, options = {}) {
    return fetch(url, options).then(res => {
      return res.json();
    });
  }

  /**
   * 使用外部传入的请求方法替换默认的fetch请求
   */
  useRequest(fetch: (url: string, options?: any) => Promise<any>) {
    if (typeof fetch !== 'function') {
      console.error('request should be a function ');
      return;
    }

    this.fetch = fetch;
  }
}

export const NemoCore = NemoCoreManager.getSingleInstance();
